import {describe,it,expect} from 'vitest';
import {explainCase} from '../lib/research/rainMismatch';
import type {Evaluation,GroundReport,Shadow} from '../lib/research/rainLab';
const now=Date.parse('2026-10-29T06:00:00Z');
const frame=(minute:number,status='RAIN',intensityClass:string|null='LT_1')=>({baseTime:`2026102904${String(minute).padStart(2,'0')}00`,validTime:`2026102904${String(minute).padStart(2,'0')}00`,status,intensityClass,kind:'OBSERVATION',capturedAt:'2026-10-29T05:00:00Z'});
function fixture(){const e:Evaluation={id:'case',target_id:'place',notification_id:539,event_type:'ACTIONABLE_RAIN_APPROACHING',target_time:'2026-10-29T04:10:00Z',created_at:'2026-10-29T03:55:14Z',state:'COMPLETE',image_state:'COMPLETE',shadow_state:'COMPLETE',snapshot:{decidedAt:'2026-10-29T03:55:14Z',location:{latitude:44,longitude:142},observation:[{...frame(0,'NO_RAIN',null),validTime:'20261029035000',baseTime:'20261029035000'}],forecast:[{...frame(10),baseTime:'20261029035000',intensityClass:'1_TO_5'}]},evidence:[{...frame(0),validTime:'20261029035500',baseTime:'20261029035500'},frame(0),frame(5),frame(10),frame(15),frame(20)]};return e;}
const explain=(e=fixture(),s?:Shadow,reports:GroundReport[]=[])=>explainCase(e,s,'20261029041000','20261029035000',.4,reports,now);
const codes=(e=fixture(),s?:Shadow,reports:GroundReport[]=[])=>explain(e,s,reports).map(x=>x.code);
describe('recorded mismatch explanations',()=>{
 it('explains the Bifuka pattern as earlier weak rain and stronger forecast, without calling it a dry false alarm',()=>{const x=explain();expect(x.find(x=>x.code==='START_EARLY')?.detail).toContain('15分早い');expect(codes()).toContain('STRONGER_FORECAST');expect(codes()).not.toContain('FALSE_RAIN');expect(codes()).toContain('METRIC_DIFFERENCE');expect(x.every(x=>!x.detail.includes('539'))).toBe(true);});
 it.each([['NO_RAIN','RAIN','FALSE_RAIN'],['RAIN','NO_RAIN','MISSED_RAIN']])('separates binary center disagreement %s / %s',(actual,predicted,code)=>{const e=fixture();(e.evidence as ReturnType<typeof frame>[]).find(x=>x.validTime==='20261029041000')!.status=actual;(e.snapshot.forecast as ReturnType<typeof frame>[])[0].status=predicted;expect(codes(e)).toContain(code);});
 it('describes later onset using adjacent observations',()=>{const e=fixture();e.evidence=[frame(10,'NO_RAIN',null),frame(15),frame(20)];expect(explain(e).find(x=>x.code==='START_LATE')?.detail).toContain('5分遅い');});
 it('does not invent onset through a missing observation',()=>{const e=fixture();e.snapshot.observation=[];e.evidence=[frame(5),frame(10)];expect(codes(e)).not.toContain('START_EARLY');expect(explain(e).find(x=>x.code==='DATA_HOLD')?.detail).toContain('断定できません');});
 it('holds future times and does not score future observations',()=>{const x=explainCase(fixture(),undefined,'20261029041000',undefined,.4,[],0);expect(x).toHaveLength(1);expect(x[0].kind).toBe('hold');});
 it('does not compare unknown or conflicting observations as dry',()=>{for(const extra of ['UNKNOWN_PIXEL','NO_RAIN']){const e=fixture();e.evidence=[...(e.evidence as ReturnType<typeof frame>[]),frame(10,extra,null)];expect(codes(e)).not.toContain('FALSE_RAIN');expect(codes(e)).toContain('DATA_HOLD');}});
 it('rejects observation frames with another issuance or invalid capture time',()=>{const e=fixture();e.evidence=[{...frame(10),baseTime:'20261029040000'},{...frame(10),capturedAt:'2026-10-29T04:09:00Z'}];expect(codes(e)).toContain('DATA_HOLD');expect(codes(e)).not.toContain('STRONGER_FORECAST');});
 it('requires ten dry minutes for an ending transition and distinguishes rain returning',()=>{const e=fixture();e.event_type='RAIN_ENDING';e.evidence=[frame(0),frame(5,'NO_RAIN',null),frame(10,'NO_RAIN',null),frame(15,'NO_RAIN',null)];expect(codes(e)).toContain('END_EARLY');e.evidence=[frame(5),frame(10,'NO_RAIN',null),frame(15),frame(20,'NO_RAIN',null)];expect(codes(e)).toContain('END_UNSTABLE');expect(codes(e)).not.toContain('END_EARLY');});
 it('keeps nearby reference reports out of ground disagreements',()=>{const r:GroundReport={evaluation_id:'case',observed_at:'2026-10-29T04:10:00Z',weather:'NO_RAIN',report_source:'NEARBY_REFERENCE',location_confirmed:true,note:''};expect(codes(fixture(),undefined,[r])).not.toContain('GROUND_DIFFERENCE');r.report_source='AT_LOCATION';expect(codes(fixture(),undefined,[r])).toContain('GROUND_DIFFERENCE');});
 it('compares area only with sufficient coverage and reports concrete percentages',()=>{const circle=(rainFraction:number,usableCoverage=1)=>({rainFraction,usableCoverage,missingFraction:1-usableCoverage,unknownFraction:0,rainComponentCount:1,centerDryHoleM2:null});const feature=(kind:string,fraction:number,coverage=1)=>({kind,baseTime:kind==='FORECAST'?'20261029035000':'20261029041000',validTime:'20261029041000',matchesInputPixel:true,capturedAt:'2026-10-29T03:56:00Z',metrics:{circles:{'500':circle(fraction,coverage)}}});const s:Shadow={evaluation_id:'case',algorithm_version:'area-shadow-v1',computed_at:'',comparison:{groups:[]},features:[feature('FORECAST',1),feature('OBSERVATION',.65)]};expect(explain(fixture(),s).find(x=>x.code==='AREA_SHRINK')?.detail).toContain('35.0ポイント減少');s.features[1]=feature('OBSERVATION',.65,.9);expect(codes(fixture(),s)).not.toContain('AREA_SHRINK');expect(codes(fixture(),s)).toContain('DATA_HOLD');});
 it('does not silently choose one of two forecast issuances when no group is selected',()=>{const e=fixture();e.snapshot.forecast=[...(e.snapshot.forecast as unknown[]),{...frame(10),baseTime:'20261029034000'}];const x=explainCase(e,undefined,'20261029041000',undefined,.4,[],now);expect(x.some(x=>x.code==='STRONGER_FORECAST')).toBe(false);expect(x.some(x=>x.code==='DATA_HOLD')).toBe(true);});
});
